// Valores anteriores del sensor
let temperatura = context.get("temperatura") ?? 23;
let humedad = context.get("humedad") ?? 50;
let luminosidad = context.get("luminosidad") ?? 250;

// Variaciones peque?as para simular un sensor real
temperatura += (Math.random() - 0.5) * 0.6;
humedad += (Math.random() - 0.5) * 2;
luminosidad += (Math.random() - 0.5) * 20;

// L?mites razonables de simulaci?n
temperatura = Math.max(18, Math.min(30, temperatura));
humedad = Math.max(30, Math.min(70, humedad));
luminosidad = Math.max(100, Math.min(500, luminosidad));

// Guardar valores para la siguiente lectura
context.set("temperatura", temperatura);
context.set("humedad", humedad);
context.set("luminosidad", luminosidad);

// Presencia simulada
const presencia = Math.random() > 0.5;

// C?digo de la exhibici?n y sensor
const exhibicionCodigo = "EXP-001";
const sensorCodigo = "SENSOR-001";

// Construir mensaje
msg.topic = `museo/exhibiciones/${exhibicionCodigo}/sensor`;

msg.payload = {
    sensorCodigo: sensorCodigo,
    exhibicionCodigo: exhibicionCodigo,
    presencia: presencia,
    temperatura: Number(temperatura.toFixed(2)),
    humedad: Number(humedad.toFixed(2)),
    luminosidad: Math.round(luminosidad),
    timestamp: new Date().toISOString()
};

return msg;

const timestamp = new Date().toISOString();
const ahoraMs = Date.now();

function uuid() { return crypto.randomUUID(); }
function clamp(v, min, max) { return Math.max(min, Math.min(max, v)); }
function red(v, d) { const f = Math.pow(10, d); return Math.round(v * f) / f; }
function entre(a, b) { return a + Math.random() * (b - a); }

// Hora efectiva: "horario de visita forzado" hace que el simulador se
// comporte como si fueran las 11:00 (util para demostrar de noche).
const horarioForzado = flow.get('horarioForzado') === true;
const horaEfectiva = horarioForzado ? 11 : new Date().getHours();
const abierto = horaEfectiva >= 9 && horaEfectiva < 18;

// Ciclo diario suave: maximo hacia las 15:00, minimo hacia las 03:00.
const ciclo = Math.cos(((horaEfectiva - 15) / 24) * 2 * Math.PI);

// ------------------------------------------------------------------
// Escenarios activos (los gestiona el nodo "Aplicar escenario").
// Estructura: { "TIPO:OBJETIVO": { tipo, objetivo, desde, hasta } }
// ------------------------------------------------------------------
const escenarios = flow.get('escenarios') || {};
function escenarioActivo(tipo, objetivo) {
    const e = escenarios[tipo + ':' + objetivo];
    return !!(e && e.hasta > ahoraMs);
}
function desconectado(sensorCodigo) {
    return escenarioActivo('SENSOR_DESCONECTADO', sensorCodigo);
}

// Modificador gradual: sube hacia el objetivo mientras el escenario esta
// activo y vuelve a 0 poco a poco cuando se restablece (sin saltos).
function pasoMod(clave, activo, objetivo, paso) {
    let v = context.get(clave);
    if (typeof v !== 'number' || !isFinite(v)) v = 0;
    if (activo) {
        v = v < objetivo ? Math.min(objetivo, v + paso) : Math.max(objetivo, v - paso);
    } else if (Math.abs(v) <= paso) {
        v = 0;
    } else {
        v -= Math.sign(v) * paso;
    }
    context.set(clave, v);
    return v;
}

// ------------------------------------------------------------------
// 6 sensores ambientales (uno por sala). La identidad es SOLO
// sensorCodigo; el backend resuelve la sala. Los valores base estan
// DENTRO del rango ideal real de cada sala (PostgreSQL), de modo que sin
// escenarios NINGUNA sala queda fuera de rango.
// ------------------------------------------------------------------
const sensoresAmbientales = [
    { sensorCodigo: 'SENSOR-AMBIENTAL-001', sala: 'SALA_1', temp: 20.0, hum: 49.0, luzDia: 110, tempAmp: 0.55, humAmp: 1.2, luzMin: 50,  luzMax: 135 },
    { sensorCodigo: 'SENSOR-AMBIENTAL-002', sala: 'SALA_2', temp: 21.0, hum: 50.0, luzDia: 215, tempAmp: 0.60, humAmp: 1.5, luzMin: 150, luzMax: 245 },
    { sensorCodigo: 'SENSOR-AMBIENTAL-003', sala: 'SALA_3', temp: 21.0, hum: 50.0, luzDia: 165, tempAmp: 0.60, humAmp: 1.5, luzMin: 90,  luzMax: 190 },
    { sensorCodigo: 'SENSOR-AMBIENTAL-004', sala: 'SALA_4', temp: 20.5, hum: 48.0, luzDia: 115, tempAmp: 0.55, humAmp: 1.4, luzMin: 50,  luzMax: 140 },
    { sensorCodigo: 'SENSOR-AMBIENTAL-005', sala: 'SALA_5', temp: 20.0, hum: 47.0, luzDia: 165, tempAmp: 0.55, humAmp: 1.4, luzMin: 80,  luzMax: 190 },
    { sensorCodigo: 'SENSOR-AMBIENTAL-006', sala: 'SALA_6', temp: 21.0, hum: 49.0, luzDia: 170, tempAmp: 0.60, humAmp: 1.4, luzMin: 90,  luzMax: 190 }
];

const K_REVERSION = 0.35;
const RUIDO_TEMP = 0.06;
const RUIDO_HUM = 0.25;
const RUIDO_LUZ = 4;

const msgs = [];

for (const s of sensoresAmbientales) {
    if (desconectado(s.sensorCodigo)) {
        continue; // SENSOR_DESCONECTADO: deja de publicar
    }

    // Escenarios de la sala (afectan a su sensor ambiental).
    const clima = escenarioActivo('FALLA_CLIMA', s.sala);
    const humAlta = escenarioActivo('HUMEDAD_ALTA', s.sala);
    const exceso = escenarioActivo('EXCESO_LUZ', s.sala);

    const modT = pasoMod('escT_' + s.sensorCodigo, clima, 6.5, 0.5);
    const modClimaH = pasoMod('escH_' + s.sensorCodigo, clima, -13, 0.5);
    const modHumAlta = pasoMod('escHumAlta_' + s.sensorCodigo, humAlta, 75 - s.hum, 0.8);
    const modLuz = pasoMod('escL_' + s.sensorCodigo, exceso, 600 - s.luzDia, 45);

    const objT = s.temp + s.tempAmp * ciclo + modT;
    const objH = s.hum + s.humAmp * ciclo + modClimaH + modHumAlta;

    let factorLuz = 0;
    if (abierto) {
        factorLuz = horaEfectiva === 9 ? 0.5 : 1;
    }
    const baseLuz = abierto
        ? clamp(s.luzDia * factorLuz + entre(-8, 8), s.luzMin, s.luzMax)
        : entre(0, 3);
    const objetivoL = baseLuz + modLuz;

    const kT = 'temp_' + s.sensorCodigo;
    const kH = 'hum_' + s.sensorCodigo;
    const kL = 'lum_' + s.sensorCodigo;

    const prevT = context.get(kT);
    const prevH = context.get(kH);
    const prevL = context.get(kL);

    const t = prevT === undefined || prevT === null
        ? objT
        : prevT + (objT - prevT) * K_REVERSION + entre(-RUIDO_TEMP, RUIDO_TEMP);
    const h = prevH === undefined || prevH === null
        ? objH
        : prevH + (objH - prevH) * K_REVERSION + entre(-RUIDO_HUM, RUIDO_HUM);
    const l = prevL === undefined || prevL === null
        ? objetivoL
        : prevL + (objetivoL - prevL) * (abierto ? 0.6 : 0.9) + entre(-RUIDO_LUZ, RUIDO_LUZ);

    // En transicion (escenario o restablecimiento) se admite un rango amplio;
    // en regimen normal se mantiene dentro del rango ideal.
    const transT = Math.abs(modT) > 0.3;
    const transH = Math.abs(modClimaH + modHumAlta) > 0.5;
    const transL = Math.abs(modLuz) > 8;

    const tf = red(clamp(t, transT ? 15 : 19.0, transT ? 40 : 21.8), 2);
    const hf = red(clamp(h, transH ? 20 : 45.2, transH ? 95 : 52.4), 2);
    const lf = red(clamp(l, 0, transL ? 800 : s.luzMax), 2);

    context.set(kT, tf);
    context.set(kH, hf);
    context.set(kL, lf);

    msgs.push({
        topic: 'museo/sensores/ambiental',
        payload: {
            mensajeId: uuid(),
            sensorCodigo: s.sensorCodigo,
            temperatura: tf,
            humedad: hf,
            luminosidad: lf,
            timestamp: timestamp
        }
    });
}

// ------------------------------------------------------------------
// 12 sensores de presencia (uno por exhibicion). Peso de popularidad
// distinto por exhibicion; la presencia dura entre 20 s y 2 min, por lo
// que NO cambia en cada ciclo de 5 s.
// ------------------------------------------------------------------
const presencias = [
    { sensorCodigo: 'SENSOR-PRESENCIA-001', sala: 'SALA_1', peso: 1.1 },
    { sensorCodigo: 'SENSOR-PRESENCIA-002', sala: 'SALA_1', peso: 2.8 },
    { sensorCodigo: 'SENSOR-PRESENCIA-003', sala: 'SALA_2', peso: 1.2 },
    { sensorCodigo: 'SENSOR-PRESENCIA-004', sala: 'SALA_2', peso: 0.4 },
    { sensorCodigo: 'SENSOR-PRESENCIA-005', sala: 'SALA_3', peso: 1.0 },
    { sensorCodigo: 'SENSOR-PRESENCIA-006', sala: 'SALA_3', peso: 1.1 },
    { sensorCodigo: 'SENSOR-PRESENCIA-007', sala: 'SALA_4', peso: 0.5 },
    { sensorCodigo: 'SENSOR-PRESENCIA-008', sala: 'SALA_4', peso: 3.0 },
    { sensorCodigo: 'SENSOR-PRESENCIA-009', sala: 'SALA_5', peso: 1.0 },
    { sensorCodigo: 'SENSOR-PRESENCIA-010', sala: 'SALA_5', peso: 1.1 },
    { sensorCodigo: 'SENSOR-PRESENCIA-011', sala: 'SALA_6', peso: 1.2 },
    { sensorCodigo: 'SENSOR-PRESENCIA-012', sala: 'SALA_6', peso: 2.6 }
];

function probabilidadInicio(hora) {
    if (hora < 9 || hora >= 18) return 0.0005;
    if ((hora >= 10 && hora < 13) || (hora >= 15 && hora < 17)) return 0.10;
    return 0.025;
}

for (const p of presencias) {
    if (desconectado(p.sensorCodigo)) {
        continue; // SENSOR_DESCONECTADO
    }
    const clave = 'presencia_' + p.sensorCodigo;
    const estado = context.get(clave) || { activa: false, hasta: 0 };
    let activa = estado.activa === true;
    let hasta = estado.hasta || 0;

    const grupo = escenarioActivo('GRUPO_VISITANTES', p.sala);
    if (grupo) {
        // Visita forzada: presencia continua en las 2 exhibiciones de la sala.
        activa = true;
        hasta = ahoraMs + 5000;
    } else if (!abierto) {
        activa = false;
        hasta = 0;
    } else if (activa) {
        if (ahoraMs >= hasta) {
            activa = false;
            hasta = 0;
        }
    } else {
        const prob = probabilidadInicio(horaEfectiva) * (p.peso / 1.5);
        if (Math.random() < prob) {
            activa = true;
            hasta = ahoraMs + entre(20, 120) * 1000;
        }
    }

    context.set(clave, { activa: activa, hasta: hasta });

    msgs.push({
        topic: 'museo/sensores/presencia',
        payload: {
            mensajeId: uuid(),
            sensorCodigo: p.sensorCodigo,
            presencia: activa,
            timestamp: timestamp
        }
    });
}

const activos = Object.keys(escenarios).filter(function (k) {
    return escenarios[k].hasta > ahoraMs;
}).length;

node.status({
    fill: activos > 0 ? 'yellow' : 'blue',
    shape: 'dot',
    text: msgs.length + ' mensajes · ' + (horarioForzado ? '11:00 forzado' : horaEfectiva + ':00') +
        (activos > 0 ? ' · ' + activos + ' escenario(s)' : '')
});
return [msgs];

function construirEstado(esc, horarioForzado) {
    const ahora = Date.now();
    const lista = Object.keys(esc || {})
        .filter(function (k) { return esc[k].hasta > ahora; })
        .map(function (k) {
            const e = esc[k];
            return {
                tipo: e.tipo,
                objetivo: e.objetivo,
                desde: e.desde,
                hasta: e.hasta,
                restantesSeg: Math.max(0, Math.round((e.hasta - ahora) / 1000))
            };
        })
        .sort(function (a, b) { return a.tipo.localeCompare(b.tipo); });
    return {
        escenarios: lista,
        horarioForzado: horarioForzado === true,
        actualizadoEn: new Date().toISOString()
    };
}

const p = msg.payload || {};
const tipo = String(p.tipo || '').toUpperCase();
const ahora = Date.now();
let esc = flow.get('escenarios') || {};
let horario = flow.get('horarioForzado') === true;
let accion = 'ignorado';

// Mapa sensor -> sala para poder restablecer una sala completa.
const sensorSala = {
    'SENSOR-AMBIENTAL-001': 'SALA_1', 'SENSOR-AMBIENTAL-002': 'SALA_2',
    'SENSOR-AMBIENTAL-003': 'SALA_3', 'SENSOR-AMBIENTAL-004': 'SALA_4',
    'SENSOR-AMBIENTAL-005': 'SALA_5', 'SENSOR-AMBIENTAL-006': 'SALA_6',
    'SENSOR-PRESENCIA-001': 'SALA_1', 'SENSOR-PRESENCIA-002': 'SALA_1',
    'SENSOR-PRESENCIA-003': 'SALA_2', 'SENSOR-PRESENCIA-004': 'SALA_2',
    'SENSOR-PRESENCIA-005': 'SALA_3', 'SENSOR-PRESENCIA-006': 'SALA_3',
    'SENSOR-PRESENCIA-007': 'SALA_4', 'SENSOR-PRESENCIA-008': 'SALA_4',
    'SENSOR-PRESENCIA-009': 'SALA_5', 'SENSOR-PRESENCIA-010': 'SALA_5',
    'SENSOR-PRESENCIA-011': 'SALA_6', 'SENSOR-PRESENCIA-012': 'SALA_6'
};

if (tipo === 'RESTABLECER') {
    if (p.todo === true) {
        esc = {};
        accion = 'restablecer todo';
    } else {
        const objetivo = String(p.sala || '').toUpperCase();
        const sensor = String(p.sensorCodigo || '').toUpperCase();
        if (objetivo) {
            Object.keys(esc).forEach(function (k) {
                const e = esc[k];
                const mismaSala = e.objetivo === objetivo || sensorSala[e.objetivo] === objetivo;
                if (mismaSala) delete esc[k];
            });
            accion = 'restablecer ' + objetivo;
        } else if (sensor) {
            Object.keys(esc).forEach(function (k) {
                if (esc[k].objetivo === sensor) delete esc[k];
            });
            accion = 'restablecer ' + sensor;
        }
    }
} else if (tipo === 'HORARIO_FORZADO') {
    horario = p.activo === true;
    accion = 'horario forzado ' + (horario ? 'ON' : 'OFF');
} else if (tipo === 'FALLA_CLIMA' || tipo === 'HUMEDAD_ALTA' || tipo === 'EXCESO_LUZ' ||
    tipo === 'GRUPO_VISITANTES' || tipo === 'SENSOR_DESCONECTADO') {
    const objetivo = tipo === 'SENSOR_DESCONECTADO'
        ? String(p.sensorCodigo || '').toUpperCase()
        : String(p.sala || '').toUpperCase();
    if (objetivo) {
        const ttl = tipo === 'GRUPO_VISITANTES' ? 2 * 60 * 1000 : 10 * 60 * 1000;
        esc[tipo + ':' + objetivo] = {
            tipo: tipo,
            objetivo: objetivo,
            desde: ahora,
            hasta: ahora + ttl
        };
        accion = tipo + ' ' + objetivo;
    }
}

flow.set('escenarios', esc);
flow.set('horarioForzado', horario);

node.status({ fill: 'green', shape: 'dot', text: accion });
node.log('Simulador: ' + accion);

msg.topic = 'museo/simulador/estado';
msg.payload = JSON.stringify(construirEstado(esc, horario));
msg.retain = true;
return msg;

function construirEstado(esc, horarioForzado) {
    const ahora = Date.now();
    const lista = Object.keys(esc || {})
        .filter(function (k) { return esc[k].hasta > ahora; })
        .map(function (k) {
            const e = esc[k];
            return {
                tipo: e.tipo,
                objetivo: e.objetivo,
                desde: e.desde,
                hasta: e.hasta,
                restantesSeg: Math.max(0, Math.round((e.hasta - ahora) / 1000))
            };
        })
        .sort(function (a, b) { return a.tipo.localeCompare(b.tipo); });
    return {
        escenarios: lista,
        horarioForzado: horarioForzado === true,
        actualizadoEn: new Date().toISOString()
    };
}

const ahora = Date.now();
const esc = flow.get('escenarios') || {};
let cambio = false;
Object.keys(esc).forEach(function (k) {
    if (!esc[k].hasta || esc[k].hasta <= ahora) {
        delete esc[k];
        cambio = true;
    }
});
if (!cambio) {
    return null;
}
flow.set('escenarios', esc);
const horario = flow.get('horarioForzado') === true;
msg.topic = 'museo/simulador/estado';
msg.payload = JSON.stringify(construirEstado(esc, horario));
msg.retain = true;
return msg;
